    46→async function processMassivePdfModification(req, res, company, signers_count) {
    47→    const arrData = req.body.data;
    48→    const fields = req.body.fields;
    49→
    50→    const details = await db.document_packages_details.findMany({
    51→        where: {
    52→            document_package_header_id: parseInt(req.body.documentHeaderId),
    53→            active: "1",
    54→        },
    55→        select: {
    56→            id: true,
    57→            name: true,
    58→            content: true,
    59→        },
    60→    });
    61→
    62→    if (!details || details.length === 0) {
    63→        return res.status(400).json({ status: false, message: 'No se encontraron documentos PDF' });
    64→    }
    65→
    66→    const pdfBuffers = {};
    67→    for (const detail of details) {
    68→        const buffer = await axios.get(detail.content, {
    69→            responseType: 'arraybuffer'
    70→        }).then(response => Buffer.from(response.data));
    71→        pdfBuffers[detail.id] = buffer;
    72→    }
    73→
    74→    const documentPackageHeader = await db.document_packages_header.findFirst({
    75→        where: {
    76→            id: parseInt(req.body.documentHeaderId),
    77→        },
    78→        select: {
    79→            name: true,
    80→            order: true,
    81→            group_signers: {
    82→                select: {
    83→                    user_id: true,
    84→                    order: true,
    85→                    user: {
    86→                        select: {
    87→                            id: true,
    88→                            email: true,
    89→                            firstname: true,
    90→                            lastname: true,
    91→                            id_number: true,
    92→                            id_type: true,
    93→                        }
    94→                    }
    95→                },
    96→            }
    97→        }
    98→    });
    99→
   100→    res.setHeader('Content-Type', 'text/event-stream');
   101→    res.setHeader('Cache-Control', 'no-cache');
   102→    res.setHeader('Connection', 'keep-alive');
   103→    res.setHeader('X-Accel-Buffering', 'no');
   104→    res.flushHeaders();
   105→
   106→    const sendEvent = (eventName, data) => {
   107→        res.write(`event: ${eventName}\ndata: ${JSON.stringify(data)}\n\n`);
   108→    };
   109→
   110→    const total = arrData.length;
   111→    let processed = 0;
   112→    let failed = 0;
   113→    const BATCH_SIZE = 5;
   114→
   115→    sendEvent('progress', { processed: 0, total, failed: 0 });
   116→
   117→    try {
   118→        async function processOneRecord(obj) {
   119→            let signer_fields = obj.signers;
   120→
   121→            const predefinedSigners = documentPackageHeader.group_signers.map(signer => ({
   122→                signer_order: signer.order,
   123→                user_id: signer.user.id,
   124→                nombres: signer.user.firstname,
   125→                apellidos: signer.user.lastname,
   126→                correo: signer.user.email,
   127→                documento: signer.user.id_number,
   128→                tipo_documento: signer.user.id_type,
   129→            }));
   130→
   131→            signer_fields = [
   132→                ...signer_fields,
   133→                ...predefinedSigners.filter(predefSigner =>
   134→                    !signer_fields.some(signer =>
   135→                        signer.user_id === predefSigner.user_id ||
   136→                        (signer.correo && predefSigner.correo &&
   137→                            signer.correo.toLowerCase().trim() === predefSigner.correo.toLowerCase().trim())
   138→                    )
   139→                )
   140→            ];
   141→
   142→            const variableValues = obj.variableValues || {};
   143→
   144→            const s3Keys = [];
   145→            for (const detail of details) {
   146→                const detailFields = fields.filter(f => {
   147→                    if (f.pdfId === undefined || f.pdfId === null) return true;
   148→                    return parseInt(f.pdfId) === parseInt(detail.id);
   149→                });
   150→
   151→                const pdfDoc = await PDFDocument.load(pdfBuffers[detail.id]);
   152→                const modifiedPdf = await modifyPdfWithFields(pdfDoc, detailFields, signer_fields, variableValues);
   153→                const s3Key = await uploadToS3(modifiedPdf, company.id);
   154→                s3Keys.push({ detailId: detail.id, s3Key, name: detail.name });
   155→            }
   156→
   157→            await db.$transaction(async (prisma) => {
   158→                const users = await getUsers(prisma, signer_fields, company.id);
   159→
   160→                const documentPackageSigner = await createDocumentPackageSigner(
   161→                    prisma,
   162→                    obj,
   163→                    req.body.user_id_creator,
   164→                    company.id,
   165→                    users[0].id,
   166→                    req.body.documentHeaderId,
   167→                    req.body.recipients,
   168→                    req.body.sendReminder,
   169→                    req.body.reminder_days_interval,
   170→                    req.body.recipientSendDate
   171→                );
   172→
   173→                await prisma.document_packages_signers_logs.create({
   174→                    data: {
   175→                        document_package_signer_id: parseInt(documentPackageSigner.id),
   176→                        event_description: "Solicitud de firma enviada",
   177→                        ip_address: req.ip ? req.ip : null,
   178→                        performed_by_user_id: parseInt(req.body.user_id_creator),
   179→                        created_at: new Date(),
   180→                    },
   181→                });
   182→
   183→                for (const { s3Key, detailId, name } of s3Keys) {
   184→                    await prisma.document_packages_signers_details_values.create({
   185→                        data: {
   186→                            document_package_detail_id: detailId,
   187→                            document_package_signer_id: parseInt(documentPackageSigner.id),
   188→                            name: name,
   189→                            company_id: parseInt(documentPackageSigner.company_id),
   190→                            visibility: 1,
   191→                            document_type_id: 1,
   192→                            fields: JSON.stringify(fields),
   193→                            signers_fields: JSON.stringify(signer_fields),
   194→                            modified_content: s3Key,
   195→                            s3_key: s3Key,
   196→                            created_at: new Date(),
   197→                            updated_at: new Date()
   198→                        }
   199→                    });
   200→                }
   201→
   202→                await sendSignRequests(res, documentPackageSigner, users, company, signer_fields, req.body.name, documentPackageHeader, prisma, req.body.signerSchedules);
   203→            }, {
   204→                maxWait: 100000,
   205→                timeout: 100000,
   206→            });
   207→        }
   208→
   209→        for (let i = 0; i < total; i += BATCH_SIZE) {
   210→            const batch = arrData.slice(i, i + BATCH_SIZE);
   211→            const results = await Promise.allSettled(
   212→                batch.map(obj => processOneRecord(obj))
   213→            );
   214→
   215→            results.forEach(result => {
   216→                if (result.status === 'fulfilled') {
   217→                    processed++;
   218→                } else {
   219→                    failed++;
   220→                    console.error('Error processing record:', result.reason);
   221→                }
   222→            });
   223→
   224→            sendEvent('progress', { processed, total, failed });
   225→        }
   226→
   227→        sendEvent('complete', {
   228→            status: true,
   229→            count: processed,
   230→            failed,
   231→            total,
   232→            message: "Solicitud enviada exitosamente"
   233→        });
   234→
   235→        res.end();
   236→
   237→    } catch (error) {
   238→        console.error('Error processing massive PDF modification:', error);
   239→        sendEvent('error', { message: 'Error en la modificación masiva del PDF' });
   240→        res.end();
   241→    }
   242→}
