   244→async function modifyPdfWithFields(pdfBuffer, fields, signer_fields, variableValues = {}) {
   245→    const pdfDoc = pdfBuffer;
   246→    const helveticaFont = await pdfDoc.embedFont(StandardFonts.Helvetica);
   247→    const timesRomanFont = await pdfDoc.embedFont(StandardFonts.TimesRoman);
   248→    const timesRomanBoldFont = await pdfDoc.embedFont(StandardFonts.TimesRomanBold);
   249→    const timesRomanItalicFont = await pdfDoc.embedFont(StandardFonts.TimesRomanItalic);
   250→    const timesRomanBoldItalicFont = await pdfDoc.embedFont(StandardFonts.TimesRomanBoldItalic);
   251→    const helveticaBoldFont = await pdfDoc.embedFont(StandardFonts.HelveticaBold);
   252→    const helveticaObliqueFont = await pdfDoc.embedFont(StandardFonts.HelveticaOblique);
   253→    const helveticaBoldObliqueFont = await pdfDoc.embedFont(StandardFonts.HelveticaBoldOblique);
   254→
   255→    const signatureFields = fields.filter(f => f.type !== 'variable');
   256→    const variableFieldsList = fields.filter(f => f.type === 'variable');
   257→
   258→    await Promise.all(signatureFields.map(async (field) => {
   259→        const { pageNumber, top, left, width, height, name } = field;
   260→        const page = pdfDoc.getPage(pageNumber - 1);
   261→        const textWidth = helveticaFont.widthOfTextAtSize(name, 12);
   262→        const textHeight = helveticaFont.heightAtSize(12);
   263→
   264→        const x = left + (width / 2) - (textWidth / 2) - 15;
   265→        const y = page.getHeight() - top - (height / 2) - (textHeight / 4);
   266→
   267→        page.drawText(name, {
   268→            x: x,
   269→            y: y + 8,
   270→            size: 12,
   271→            font: helveticaFont
   272→        });
   273→
   274→        const signer = signer_fields.find(s => `[$FIRMA${s.signer_order}]` == name);
   275→
   276→        if (signer) {
   277→            const fullName = `${signer.nombres} ${signer.apellidos}`;
   278→            const docType = await getDocumentTypeName(signer.tipo_documento);
   279→            const docTypeAndNumber = `${docType.abbreviation}: ${signer.documento}`;
   280→
   281→            const fullNameWidth = timesRomanFont.widthOfTextAtSize(fullName, 10);
   282→            const docTypeAndNumberWidth = timesRomanFont.widthOfTextAtSize(docTypeAndNumber, 10);
   283→
   284→            const xFullName = x + (textWidth / 2) - (fullNameWidth / 2);
   285→
   286→            const xDocTypeAndNumber = x + (textWidth / 2) - (docTypeAndNumberWidth / 2);
   287→
   288→            page.drawText(fullName, {
   289→                x: xFullName,
   290→                y: y - textHeight - 8,
   291→                size: 10,
   292→                font: timesRomanFont
   293→            });
   294→
   295→            page.drawText(docTypeAndNumber, {
   296→                x: xDocTypeAndNumber,
   297→                y: y - textHeight - 22,
   298→                size: 10,
   299→                font: timesRomanFont
   300→            });
   301→        }
   302→    }));
   303→
   304→    for (const field of variableFieldsList) {
   305→        const { pageNumber, top, left, width, height, name, fontFamily, fontColor, fontWeight, fontStyle } = field;
   306→        const page = pdfDoc.getPage(pageNumber - 1);
   307→
   308→        const varName = name.replace(/\[\$|\]/g, '');
   309→        const value = variableValues[varName] || '';
   310→
   311→        if (!value) continue;
   312→
   313→        const isBold = fontWeight && parseInt(fontWeight) >= 600;
   314→        const isItalic = fontStyle === 'italic';
   315→        const isSerif = !fontFamily || fontFamily.includes('Times') || fontFamily.includes('serif') || fontFamily.includes('Garamond') || fontFamily.includes('Georgia') || fontFamily.includes('Lora');
   316→
   317→        let selectedFont;
   318→        if (isSerif) {
   319→            if (isBold && isItalic) selectedFont = timesRomanBoldItalicFont;
   320→            else if (isBold) selectedFont = timesRomanBoldFont;
   321→            else if (isItalic) selectedFont = timesRomanItalicFont;
   322→            else selectedFont = timesRomanFont;
   323→        } else {
   324→            if (isBold && isItalic) selectedFont = helveticaBoldObliqueFont;
   325→            else if (isBold) selectedFont = helveticaBoldFont;
   326→            else if (isItalic) selectedFont = helveticaObliqueFont;
   327→            else selectedFont = helveticaFont;
   328→        }
   329→
   330→        const maxFontSize = Math.min(height * 0.6, 32);
   331→        let fontSize = Math.max(8, maxFontSize);
   332→
   333→        let textWidth = selectedFont.widthOfTextAtSize(value, fontSize);
   334→        while (textWidth > width - 4 && fontSize > 6) {
   335→            fontSize -= 0.5;
   336→            textWidth = selectedFont.widthOfTextAtSize(value, fontSize);
   337→        }
   338→
   339→        const textHeight = selectedFont.heightAtSize(fontSize);
   340→
   341→        const x = left + (width / 2) - (textWidth / 2);
   342→        const y = page.getHeight() - top - (height / 2) + (textHeight / 4);
   343→
   344→        let color = rgb(0.39, 0.39, 0.38);
   345→        if (fontColor && fontColor.startsWith('#')) {
   346→            const hex = fontColor.replace('#', '');
   347→            const r = parseInt(hex.substring(0, 2), 16) / 255;
   348→            const g = parseInt(hex.substring(2, 4), 16) / 255;
   349→            const b = parseInt(hex.substring(4, 6), 16) / 255;
   350→            color = rgb(r, g, b);
   351→        }
   352→
   353→        page.drawText(value, {
   354→            x: x,
   355→            y: y,
   356→            size: fontSize,
   357→            font: selectedFont,
   358→            color: color,
   359→        });
   360→    }
   361→
   362→    return await pdfDoc.save();
   363→}
