   377→async function uploadToS3(pdfBuffer, companyId) {
   378→
   379→    const uniqueId = crypto.randomBytes(16).toString("hex");
   380→
   381→    const key = `stored_files/${companyId}/${uniqueId}`;
   382→    const uploadParams = {
   383→        Bucket: process.env.S3_BUCKET,
   384→        Key: key,
   385→        Body: pdfBuffer,
   386→        ContentType: 'application/pdf',
   387→    };
   388→
   389→    await s3Client.send(new PutObjectCommand(uploadParams));
   390→    return key; 
   391→}
