   451→async function createDocumentPackageSigner(prisma, req, creator, companyId, userId, documentHeaderId, recipients, send_reminder, reminder_days_interval, recipientSendDate) {
   452→    const fingerprint = await generateFingerPrint();
   453→
   454→    const expires_date = new Date(req.expires_in_days);
   455→    formatted_expires_date = expires_date.toISOString();
   456→    
   457→    const current_date = new Date();
   458→    const formatted_current_date = current_date.toISOString();
   459→
   460→    const request = await prisma.document_packages_signers.create({
   461→        data: {
   462→            document_package_header_id: parseInt(documentHeaderId),
   463→            user_id: parseInt(userId),
   464→            company_id: parseInt(companyId),
   465→            status: "send",
   466→            token: "",
   467→            is_pdf: 1,
   468→            sent_sign_request_at: formatted_current_date,
   469→            fingerprint: fingerprint.replace(":", ""),
   470→            ip_address: req.ip,
   471→            from_api: 1,
   472→            user_id_creator: parseInt(creator),
   473→            active: "1",
   474→            reminder_days_interval: reminder_days_interval ? reminder_days_interval : null,
   475→            send_reminder: send_reminder == 1 ? true : false,
   476→            expires_in_days: formatted_expires_date,
   477→            recipient_scheduled_send_at: recipientSendDate ? new Date(recipientSendDate) : null,
   478→            created_at: new Date(),
   479→            updated_at: new Date()
   480→        }
   481→    });
   482→
   483→    if (recipients.length > 0) {
   484→        const validRecipients = recipients.filter(recipient => recipient.email && recipient.email.trim() !== '');
   485→
   486→        if (validRecipients.length > 0) {
   487→            for (let i = 0; i < validRecipients.length; i++) {
   488→                const recipient = validRecipients[i];
   489→    
   490→                await prisma.request_recipients.create({
   491→                    data: {
   492→                        document_package_signer_id: request.id,
   493→                        type: 1,
   494→                        email: recipient.email,
   495→                        created_at: new Date(),
   496→                        updated_at: new Date(),
   497→                    },
   498→                });
   499→    
   500→                await prisma.document_packages_signers_logs.create({
   501→                    data: {
   502→                        document_package_signer_id: request.id,
   503→                        event_description: `Destinatario agregado: ${recipient.email}`,
   504→                        ip_address: req.ip ? req.ip : null,
   505→                        performed_by_user_id: parseInt(creator),
   506→                        created_at: new Date(),
   507→                    },
   508→                });
   509→            }
   510→        } else {
