   528→            });
   529→
   530→            const fingerprint = await generateFingerPrint();
   531→
   532→            const signerField = signerFields.find(field => field.correo.toLowerCase().trim() == user.email.toLowerCase().trim());
   533→
   534→            if (!signerField) {
   535→                console.error(`No se encontró signerField para el usuario con correo: ${user.email}`);
   536→                continue;
   537→            }
   538→
   539→            const orderMatch = signerField.signer_order;
   540→            const order = orderMatch ? parseInt(orderMatch) : users.indexOf(user) + 1;
   541→
   542→            const schedule = signerSchedules.find(s => parseInt(s.signer_order) === order);
   543→            const scheduledSendAt = schedule && schedule.send_datetime ? new Date(schedule.send_datetime) : null;
   544→            const signerStatus = scheduledSendAt ? "scheduled" : "send";
   545→
   546→            await prisma.document_signers.create({
