   554→                    fingerprint: fingerprint.replace(":", ""),
   555→                    expires_in_days: documentPackageSigner.expires_in_days,
   556→                    scheduled_send_at: scheduledSendAt,
   557→                    created_at: new Date(),
   558→                    updated_at: new Date()
   559→                },
   560→            });
   561→
   562→            const url = `${process.env.ENV_URL}${token}`;
   563→
   564→            if (documentPackageHeader.order == 1 && parseInt(order) === 1) {
   565→                requests.push({
   566→                    email: user.email,
   567→                    company: company,
   568→                    firstname: user.firstname,
   569→                    lastname: user.lastname,
   570→                    passwordGenerated: genApiKey.generateApiKey({ method: "base32", dashes: false }),
