async function updatePdfContentMassive(req, res) {
    try {
        const company = await getCompany(req.body.company_id);
        if (!company) {
            return res.status(400).send({ status: false, message: "API KEY incorrecta" });
        }

        const companyPackages = await getCompanyPackages(company.company_id);
        if (!companyPackages) {
            return res.status(400).send({ status: false, message: "No tiene paquetes asignados" });
        }

        const storage = await service.getStorageUsed(company.company_id);
        if (isStorageExceeded(company, storage)) {
            return res.status(400).send({ status: false, message: "Se ha superado la capacidad de almacenamiento. Por favor, actualice su plan." });
        }

        const signers_count = req.body.data.length;

        await processMassivePdfModification(req, res, company, signers_count);

    } catch (error) {
        console.error('Error updating PDF:', error);

        if (!res.headersSent) {
            res.status(500).json({ status: false, message: 'Error updating PDF' });
        }
    }
}

async function processMassivePdfModification(req, res, company, signers_count) {
    const arrData = req.body.data;
    const fields = req.body.fields;

    const details = await db.document_packages_details.findMany({
        where: {
            document_package_header_id: parseInt(req.body.documentHeaderId),
            active: "1",
        },
        select: {
            id: true,
            name: true,
            content: true,
        },
    });

    if (!details || details.length === 0) {
        return res.status(400).json({ status: false, message: 'No se encontraron documentos PDF' });
    }

    const pdfBuffers = {};
    for (const detail of details) {
        const buffer = await axios.get(detail.content, {
            responseType: 'arraybuffer'
        }).then(response => Buffer.from(response.data));
        pdfBuffers[detail.id] = buffer;
    }

    const documentPackageHeader = await db.document_packages_header.findFirst({
        where: {
            id: parseInt(req.body.documentHeaderId),
        },
        select: {
            name: true,
            order: true,
            group_signers: {
                select: {
                    user_id: true,
                    order: true,
                    user: {
                        select: {
                            id: true,
                            email: true,
                            firstname: true,
                            lastname: true,
                            id_number: true,
                            id_type: true,
                        }
                    }
                },
            }
        }
    });

    res.setHeader('Content-Type', 'text/event-stream');
    res.setHeader('Cache-Control', 'no-cache');
    res.setHeader('Connection', 'keep-alive');
    res.setHeader('X-Accel-Buffering', 'no');
    res.flushHeaders();

    const sendEvent = (eventName, data) => {
        res.write(`event: ${eventName}\ndata: ${JSON.stringify(data)}\n\n`);
    };

    const total = arrData.length;
    let processed = 0;
    let failed = 0;
    const BATCH_SIZE = 5;

    sendEvent('progress', { processed: 0, total, failed: 0 });

    try {
        async function processOneRecord(obj) {
            let signer_fields = obj.signers;

            const predefinedSigners = documentPackageHeader.group_signers.map(signer => ({
                signer_order: signer.order,
                user_id: signer.user.id,
                nombres: signer.user.firstname,
                apellidos: signer.user.lastname,
                correo: signer.user.email,
                documento: signer.user.id_number,
                tipo_documento: signer.user.id_type,
            }));

            signer_fields = [
                ...signer_fields,
                ...predefinedSigners.filter(predefSigner =>
                    !signer_fields.some(signer =>
                        signer.user_id === predefSigner.user_id ||
                        (signer.correo && predefSigner.correo &&
                            signer.correo.toLowerCase().trim() === predefSigner.correo.toLowerCase().trim())
                    )
                )
            ];

            const variableValues = obj.variableValues || {};

            const s3Keys = [];
            for (const detail of details) {
                const detailFields = fields.filter(f => {
                    if (f.pdfId === undefined || f.pdfId === null) return true;
                    return parseInt(f.pdfId) === parseInt(detail.id);
                });

                const pdfDoc = await PDFDocument.load(pdfBuffers[detail.id]);
                const modifiedPdf = await modifyPdfWithFields(pdfDoc, detailFields, signer_fields, variableValues);
                const s3Key = await uploadToS3(modifiedPdf, company.id);
                s3Keys.push({ detailId: detail.id, s3Key, name: detail.name });
            }

            await db.$transaction(async (prisma) => {
                const users = await getUsers(prisma, signer_fields, company.id);

                const documentPackageSigner = await createDocumentPackageSigner(
                    prisma,
                    obj,
                    req.body.user_id_creator,
                    company.id,
                    users[0].id,
                    req.body.documentHeaderId,
                    req.body.recipients,
                    req.body.sendReminder,
                    req.body.reminder_days_interval,
                    req.body.recipientSendDate
                );

                await prisma.document_packages_signers_logs.create({
                    data: {
                        document_package_signer_id: parseInt(documentPackageSigner.id),
                        event_description: "Solicitud de firma enviada",
                        ip_address: req.ip ? req.ip : null,
                        performed_by_user_id: parseInt(req.body.user_id_creator),
                        created_at: new Date(),
                    },
                });

                for (const { s3Key, detailId, name } of s3Keys) {
                    await prisma.document_packages_signers_details_values.create({
                        data: {
                            document_package_detail_id: detailId,
                            document_package_signer_id: parseInt(documentPackageSigner.id),
                            name: name,
                            company_id: parseInt(documentPackageSigner.company_id),
                            visibility: 1,
                            document_type_id: 1,
                            fields: JSON.stringify(fields),
                            signers_fields: JSON.stringify(signer_fields),
                            modified_content: s3Key,
                            s3_key: s3Key,
                            created_at: new Date(),
                            updated_at: new Date()
                        }
                    });
                }

                await sendSignRequests(res, documentPackageSigner, users, company, signer_fields, req.body.name, documentPackageHeader, prisma, req.body.signerSchedules);
            }, {
                maxWait: 100000,
                timeout: 100000,
            });
        }

        for (let i = 0; i < total; i += BATCH_SIZE) {
            const batch = arrData.slice(i, i + BATCH_SIZE);
            const results = await Promise.allSettled(
                batch.map(obj => processOneRecord(obj))
            );

            results.forEach(result => {
                if (result.status === 'fulfilled') {
                    processed++;
                } else {
                    failed++;
                    console.error('Error processing record:', result.reason);
                }
            });

            sendEvent('progress', { processed, total, failed });
        }

        sendEvent('complete', {
            status: true,
            count: processed,
            failed,
            total,
            message: "Solicitud enviada exitosamente"
        });

        res.end();

    } catch (error) {
        console.error('Error processing massive PDF modification:', error);
        sendEvent('error', { message: 'Error en la modificación masiva del PDF' });
        res.end();
    }
}

async function modifyPdfWithFields(pdfBuffer, fields, signer_fields, variableValues = {}) {
    const pdfDoc = pdfBuffer;
    const helveticaFont = await pdfDoc.embedFont(StandardFonts.Helvetica);
    const timesRomanFont = await pdfDoc.embedFont(StandardFonts.TimesRoman);
    const timesRomanBoldFont = await pdfDoc.embedFont(StandardFonts.TimesRomanBold);
    const timesRomanItalicFont = await pdfDoc.embedFont(StandardFonts.TimesRomanItalic);
    const timesRomanBoldItalicFont = await pdfDoc.embedFont(StandardFonts.TimesRomanBoldItalic);
    const helveticaBoldFont = await pdfDoc.embedFont(StandardFonts.HelveticaBold);
    const helveticaObliqueFont = await pdfDoc.embedFont(StandardFonts.HelveticaOblique);
    const helveticaBoldObliqueFont = await pdfDoc.embedFont(StandardFonts.HelveticaBoldOblique);

    const signatureFields = fields.filter(f => f.type !== 'variable');
    const variableFieldsList = fields.filter(f => f.type === 'variable');

    await Promise.all(signatureFields.map(async (field) => {
        const { pageNumber, top, left, width, height, name } = field;
        const page = pdfDoc.getPage(pageNumber - 1);
        const textWidth = helveticaFont.widthOfTextAtSize(name, 12);
        const textHeight = helveticaFont.heightAtSize(12);

        const x = left + (width / 2) - (textWidth / 2) - 15;
        const y = page.getHeight() - top - (height / 2) - (textHeight / 4);

        page.drawText(name, {
            x: x,
            y: y + 8,
            size: 12,
            font: helveticaFont
        });

        const signer = signer_fields.find(s => `[$FIRMA${s.signer_order}]` == name);

        if (signer) {
            const fullName = `${signer.nombres} ${signer.apellidos}`;
            const docType = await getDocumentTypeName(signer.tipo_documento);
            const docTypeAndNumber = `${docType.abbreviation}: ${signer.documento}`;

            const fullNameWidth = timesRomanFont.widthOfTextAtSize(fullName, 10);
            const docTypeAndNumberWidth = timesRomanFont.widthOfTextAtSize(docTypeAndNumber, 10);

            const xFullName = x + (textWidth / 2) - (fullNameWidth / 2);

            const xDocTypeAndNumber = x + (textWidth / 2) - (docTypeAndNumberWidth / 2);

            page.drawText(fullName, {
                x: xFullName,
                y: y - textHeight - 8,
                size: 10,
                font: timesRomanFont
            });

            page.drawText(docTypeAndNumber, {
                x: xDocTypeAndNumber,
                y: y - textHeight - 22,
                size: 10,
                font: timesRomanFont
            });
        }
    }));

    for (const field of variableFieldsList) {
        const { pageNumber, top, left, width, height, name, fontFamily, fontColor, fontWeight, fontStyle } = field;
        const page = pdfDoc.getPage(pageNumber - 1);

        const varName = name.replace(/\[\$|\]/g, '');
        const value = variableValues[varName] || '';

        if (!value) continue;

        const isBold = fontWeight && parseInt(fontWeight) >= 600;
        const isItalic = fontStyle === 'italic';
        const isSerif = !fontFamily || fontFamily.includes('Times') || fontFamily.includes('serif') || fontFamily.includes('Garamond') || fontFamily.includes('Georgia') || fontFamily.includes('Lora');

        let selectedFont;
        if (isSerif) {
            if (isBold && isItalic) selectedFont = timesRomanBoldItalicFont;
            else if (isBold) selectedFont = timesRomanBoldFont;
            else if (isItalic) selectedFont = timesRomanItalicFont;
            else selectedFont = timesRomanFont;
        } else {
            if (isBold && isItalic) selectedFont = helveticaBoldObliqueFont;
            else if (isBold) selectedFont = helveticaBoldFont;
            else if (isItalic) selectedFont = helveticaObliqueFont;
            else selectedFont = helveticaFont;
        }

        const maxFontSize = Math.min(height * 0.6, 32);
        let fontSize = Math.max(8, maxFontSize);

        let textWidth = selectedFont.widthOfTextAtSize(value, fontSize);
        while (textWidth > width - 4 && fontSize > 6) {
            fontSize -= 0.5;
            textWidth = selectedFont.widthOfTextAtSize(value, fontSize);
        }

        const textHeight = selectedFont.heightAtSize(fontSize);

        const x = left + (width / 2) - (textWidth / 2);
        const y = page.getHeight() - top - (height / 2) + (textHeight / 4);

        let color = rgb(0.39, 0.39, 0.38);
        if (fontColor && fontColor.startsWith('#')) {
            const hex = fontColor.replace('#', '');
            const r = parseInt(hex.substring(0, 2), 16) / 255;
            const g = parseInt(hex.substring(2, 4), 16) / 255;
            const b = parseInt(hex.substring(4, 6), 16) / 255;
            color = rgb(r, g, b);
        }

        page.drawText(value, {
            x: x,
            y: y,
            size: fontSize,
            font: selectedFont,
            color: color,
        });
    }

    return await pdfDoc.save();
}

async function getDocumentTypeName(id) {
    return await db.identification_types.findFirst({
        where: {
             id: parseInt(id)
        },
        select: { 
            abbreviation: true 
        }
    });

}

async function uploadToS3(pdfBuffer, companyId) {

    const uniqueId = crypto.randomBytes(16).toString("hex");

    const key = `stored_files/${companyId}/${uniqueId}`;
    const uploadParams = {
        Bucket: process.env.S3_BUCKET,
        Key: key,
        Body: pdfBuffer,
        ContentType: 'application/pdf',
    };

    await s3Client.send(new PutObjectCommand(uploadParams));
    return key; 
}

async function getUsers(prisma, signerFields, companyId) {
    const users = [];
    for (const signer of signerFields) {
        const user = await findOrCreateUser(prisma, signer, companyId);
        users.push(user);
    }
    return users;
}

async function findOrCreateUser(prisma, signer, companyId) {

    let user;

    if (signer.user_id) {
        user = await prisma.users.findFirst({
            where: {
                id: parseInt(signer.user_id)
            },
            select: { id: true, email: true, firstname: true, lastname: true, id_number: true, doc_type: true }
        });
    }

    if (!user) {
        user = await prisma.users.findFirst({
            where: {
                OR: [
                    { email: signer.correo },
                   // { id_number: String(signer.documento), id_type: parseInt(signer.tipo_documento) }
                ]
            },
            select: { id: true, email: true, firstname: true, lastname: true, id_number: true, doc_type: true }
        });
    }

    if (!user) {
        user = await prisma.users.create({
            data: {
                firstname: signer.nombres,
                lastname: signer.apellidos,
                email: signer.correo,
                password: genApiKey.generateApiKey({ method: "base32", dashes: false }),
                type: "3",
                role_id: "3",
                signer: "1",
                active: "1",
                accept_terms_and_conditions: "false",
                id_number: String(signer.documento),
                id_type: parseInt(signer.tipo_documento),
                company_id: companyId,
                two_factor_login: "false",
                created_at: new Date()
            }
        });
    }

    return user;
}

async function createDocumentPackageSigner(prisma, req, creator, companyId, userId, documentHeaderId, recipients, send_reminder, reminder_days_interval, recipientSendDate) {
    const fingerprint = await generateFingerPrint();

    const expires_date = new Date(req.expires_in_days);
    formatted_expires_date = expires_date.toISOString();

    const current_date = new Date();
    const formatted_current_date = current_date.toISOString();

    const request = await prisma.document_packages_signers.create({
        data: {
            document_package_header_id: parseInt(documentHeaderId),
            user_id: parseInt(userId),
            company_id: parseInt(companyId),
            status: "send",
            token: "",
            is_pdf: 1,
            sent_sign_request_at: formatted_current_date,
            fingerprint: fingerprint.replace(":", ""),
            ip_address: req.ip,
            from_api: 1,
            user_id_creator: parseInt(creator),
            active: "1",
            reminder_days_interval: reminder_days_interval ? reminder_days_interval : null,
            send_reminder: send_reminder == 1 ? true : false,
            expires_in_days: formatted_expires_date,
            recipient_scheduled_send_at: recipientSendDate ? new Date(recipientSendDate) : null,
            created_at: new Date(),
            updated_at: new Date()
        }
    });

    if (recipients.length > 0) {
        const validRecipients = recipients.filter(recipient => recipient.email && recipient.email.trim() !== '');

        if (validRecipients.length > 0) {
            for (let i = 0; i < validRecipients.length; i++) {
                const recipient = validRecipients[i];

                await prisma.request_recipients.create({
                    data: {
                        document_package_signer_id: request.id,
                        type: 1,
                        email: recipient.email,
                        created_at: new Date(),
                        updated_at: new Date(),
                    },
                });

                await prisma.document_packages_signers_logs.create({
                    data: {
                        document_package_signer_id: request.id,
                        event_description: `Destinatario agregado: ${recipient.email}`,
                        ip_address: req.ip ? req.ip : null,
                        performed_by_user_id: parseInt(creator),
                        created_at: new Date(),
                    },
                });
            }
        } else {
            console.log("No hay destinatarios válidos");
        }
    }

    return request;
}


async function sendSignRequests(res, documentPackageSigner, users, company, signerFields, packageName, documentPackageHeader, prisma, signerSchedules = []) {
    const requests = [];
    let requestSending = false;

    try {
        for (const user of users) {
            const token = service.createCustomToken({
                id: user.id,
                document_package_signer_id: documentPackageSigner.id,
            });

            const fingerprint = await generateFingerPrint();

            const signerField = signerFields.find(field => field.correo.toLowerCase().trim() == user.email.toLowerCase().trim());

            if (!signerField) {
                console.error(`No se encontró signerField para el usuario con correo: ${user.email}`);
                continue;
            }

            const orderMatch = signerField.signer_order;
            const order = orderMatch ? parseInt(orderMatch) : users.indexOf(user) + 1;

            const schedule = signerSchedules.find(s => parseInt(s.signer_order) === order);
            const scheduledSendAt = schedule && schedule.send_datetime ? new Date(schedule.send_datetime) : null;
            const signerStatus = scheduledSendAt ? "scheduled" : "send";

            await prisma.document_signers.create({
                data: {
                    document_package_signer_id: documentPackageSigner.id,
                    user_id: parseInt(user.id),
                    order: order,
                    status: signerStatus,
                    token: token,
                    sent_sign_request_at: new Date(),
                    fingerprint: fingerprint.replace(":", ""),
                    expires_in_days: documentPackageSigner.expires_in_days,
                    scheduled_send_at: scheduledSendAt,
                    created_at: new Date(),
                    updated_at: new Date()
                },
            });

            const url = `${process.env.ENV_URL}${token}`;

            if (documentPackageHeader.order == 1 && parseInt(order) === 1) {
                requests.push({
                    email: user.email,
                    company: company,
                    firstname: user.firstname,
                    lastname: user.lastname,
                    passwordGenerated: genApiKey.generateApiKey({ method: "base32", dashes: false }),
                    date: documentPackageSigner.expires_in_days.toLocaleDateString('es-ES'),
                    time: documentPackageSigner.expires_in_days.toLocaleTimeString(),
                    _url: url,
                    company_email: company.email,
                    sendRequest: true
                });
            }

            if (documentPackageHeader.order === 2 && !scheduledSendAt) {
                requests.push({
                    id: user.id,
                    document_package_signer_id: documentPackageSigner.id,
                    email: user.email,
                    company: company,
                    firstname: user.firstname,
                    lastname: user.lastname,
                    passwordGenerated: genApiKey.generateApiKey({ method: "base32", dashes: false }),
                    date: documentPackageSigner.expires_in_days.toLocaleDateString('es-ES'),
                    time: documentPackageSigner.expires_in_days.toLocaleTimeString(),
                    _url: url,
                    company_email: company.email,
                    sendRequest: true
                });
            }
        }

        requestSending = true;

    } catch (error) {
        console.error("Error al generar las solicitudes de firma:", error);
    }


    await Promise.all(requests.map(async (user) => {
        if (requestSending) {

            if (user.sendRequest) {
                await service.sendSolicitudFirma(
                    user.email,
                    user.company.avatar,
                    `${user.firstname} ${user.lastname}`,
                    user.company.fiscal_name,
                    user.company.fiscal_name,
                    user.passwordGenerated,
                    user.date,
                    user.time,
                    user._url,
                    user.company_email,
                    packageName,
                    user.company.advanced_settings[0].email_message || "",
                    user.id,
                    user.document_package_signer_id,
                    user.company.id
                );
            }
        }
    }));

}

async function getCompany(companyId) {
    const branch = await db.companies.findFirst({
        where: { id: companyId },
        select: {
            id: true,
            company_parent_id: true,
            avatar: true,
            company_name: true,
        }
    });

    if (!branch) return null;

    const parentCompanyId = branch.company_parent_id;

    const main = await db.companies.findFirst({
        where: { id: parentCompanyId ?? branch.id },
        select: {
            id: true,
            storage: true,
            email: true,
            fiscal_name: true,
            advanced_settings: {
                select: {
                    email_message: true,
                }
            }
        }
    });

    if (!main) return null;

    return {
        id: branch.id, 
        company_id: main.id,
        storage: main.storage,
        email: main.email,
        avatar: branch.avatar, 
        fiscal_name: main.fiscal_name,
        company_name: branch.company_name,
        advanced_settings: main.advanced_settings,

    };
}


async function getCompanyPackages(companyId) {
    return await db.company_packages_assignments.findFirst({
        where: { company_id: parseInt(companyId), status: 1 },
        select: { id: true, units: true, remaining_units: true, updated_at: true }
    });
}

function isStorageExceeded(company, storage) {
    const lastUpdated = moment(company?.advanced_settings[0].updated_at);
    const daysSinceLastUpdate = moment().diff(lastUpdated, 'days');
    return storage >= company?.advanced_settings[0]?.storage_capacity || daysSinceLastUpdate >= company?.advanced_settings[0]?.storage_time_limit;
}

async function generateFingerPrint() {
    // Importing crypto module
    const { X509Certificate, sign } = require("crypto");

    const fs = require("fs");

    const x509 = new X509Certificate(fs.readFileSync("./my_cert.pem", "utf-8"));

    const value = x509.fingerprint;
    return value.replace(/:/g, "").toLowerCase();
}

async function downloadRecipientsTemplate(req, res) {
    try {
        const workbook = new ExcelJS.Workbook();
        const sheet = workbook.addWorksheet('Remitentes');
        sheet.columns = [{ header: 'Correos', key: 'email', width: 40 }];

        res.setHeader('Content-Type', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
        res.setHeader('Content-Disposition', 'attachment; filename="plantilla_remitentes.xlsx"');
        await workbook.xlsx.write(res);
        res.end();
    } catch (error) {
        console.error('Error generando plantilla de remitentes:', error);
        res.status(500).json({ status: false, message: 'Error generando plantilla' });
    }
}

async function parseRecipientsFile(req, res) {
    try {
        if (!req.file) {
            return res.status(400).json({ status: false, message: 'No se recibió ningún archivo' });
        }

        const workbook = new ExcelJS.Workbook();
        await workbook.xlsx.readFile(req.file.path);
        const sheet = workbook.worksheets[0];

        const emails = [];
        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

        sheet.eachRow((row, rowNumber) => {
            if (rowNumber === 1) return;
            const cellValue = row.getCell(1).value;
            let email = '';

            if (cellValue && typeof cellValue === 'object') {
                email = cellValue.text ? String(cellValue.text).trim() : '';
            } else {
                email = cellValue ? String(cellValue).trim() : '';
            }

            if (email && emailRegex.test(email)) {
                emails.push(email);
            }
        });

        fs.unlink(req.file.path, () => {});

        if (emails.length === 0) {
            return res.status(400).json({ status: false, message: 'No se encontraron correos válidos en el archivo' });
        }

        res.json({ status: true, emails });
    } catch (error) {
        console.error('Error parseando archivo de remitentes:', error);
        res.status(500).json({ status: false, message: 'Error procesando el archivo' });
    }
}

module.exports = {
    updatePdfContentMassive,
    downloadRecipientsTemplate,
    parseRecipientsFile,
};

