"use strict";
const config = require("../config");
const jwt = require("jsonwebtoken");
const fs = require("fs");
const { PrismaClient } = require("@prisma/client");
const db = new PrismaClient();
const service = require("../services");
const { getPage, releasePage } = require("../services/puppeteer/browserPool");
const export_service = require("../export");
const { S3Client, PutObjectCommand, GetObjectCommand } = require('@aws-sdk/client-s3');
const { LambdaClient, InvokeCommand } = require('@aws-sdk/client-lambda');
const lambdaClient = new LambdaClient({ region: process.env.AWS_REGION });
const axios = require('axios'); 
const os = require('os');
const moment = require('moment-timezone');
const cheerio = require('cheerio');
const { PDFDocument, rgb  } = require('pdf-lib');
const crypto = require('crypto');
const qr = require('qrcode');
const UAParser = require('ua-parser-js');
const { generateHeaderTemplate, generateFooterTemplate } = require("../services/pdfService");
const { Upload } = require("@aws-sdk/lib-storage");

const s3Client = new S3Client({ region: 'us-east-1' });

require("dotenv").config();

async function getSignRequests(req, res) {
    try {
        const { filters, itemsPerPage = 10, page = 1, company_id, user_id } = req.body;
        const skip = (page - 1) * itemsPerPage;
        const currentUserId = parseInt(user_id);

        const originalCompany = await db.companies.findFirst({
            where: { id: parseInt(company_id) },
            select: { id: true, company_parent_id: true }
        });

        const realCompanyId = originalCompany?.company_parent_id || originalCompany?.id;

        const userMemberships = await db.user_group_membership.findMany({
            where: { user_id: currentUserId },
            select: { group_id: true }
        });
        const userGroupIds = userMemberships.map(m => m.group_id);

        const filterConditions = [];

        if (filters.created_at) {
            const startDate = new Date(filters.created_at);
            const endDate = new Date(startDate);
            endDate.setDate(startDate.getDate() + 1);
            filterConditions.push({ created_at: { gte: startDate, lt: endDate } });
        }
        if (filters.updated_at) {
            const startDate = new Date(filters.updated_at);
            const endDate = new Date(startDate);
            endDate.setDate(startDate.getDate() + 1);
            filterConditions.push({ updated_at: { gte: startDate, lt: endDate } });
        }
        if (filters.status?.length > 0) {
            filterConditions.push({ status: { in: filters.status } });
        }
        if (filters.processing_status?.length > 0) {
            filterConditions.push({ processing_status: { in: filters.processing_status.map(Number) } });
        }
        if (filters.ids?.length > 0) {
            filterConditions.push({ id: { in: filters.ids.map(BigInt) } });
        }
        if (filters.id) {
            filterConditions.push({ id: BigInt(filters.id) });
        }

        const signerUserFilter = {};
        if (filters.id_type?.length > 0) signerUserFilter.id_type = { in: filters.id_type.map(Number) };
        if (filters.id_number?.length > 0) signerUserFilter.id_number = { in: filters.id_number };
        if (filters.signer) {
            signerUserFilter.OR = [
                { firstname: { contains: filters.signer.toLowerCase() } },
                { lastname: { contains: filters.signer.toLowerCase() } },
            ];
        }
        if (Object.keys(signerUserFilter).length > 0) {
            filterConditions.push({ signers: { some: { users: signerUserFilter } } });
        }

        if (filters.signatures === 0) {
            filterConditions.push({ signers: { none: { status: 'accepted' } } });
        } else if (filters.signatures === 1) {
            filterConditions.push({ signers: { some: { status: 'accepted' } } });
            filterConditions.push({ signers: { some: { status: { not: 'accepted' } } } });
        }

        if (filters.document_packages?.length > 0) {
            const packageConditions = [];
            const packageIds = filters.document_packages.map(p => BigInt(p)).filter(id => id !== 0n);
            if (packageIds.length > 0) {
                packageConditions.push({ document_package_header_id: { in: packageIds } });
            }
            if (filters.document_packages.includes(0)) {
                packageConditions.push({ is_pdf: 1, document_package_header_id: null });
            }
            if (packageConditions.length > 0) {
                filterConditions.push({ OR: packageConditions });
            }
        }

         const permissionClause = {
            OR: [
                { document_packages_header: { user_id_creator: currentUserId } },
                {
                    document_packages_header: {
                        document_permissions: {
                            some: {
                                OR: [
                                    { grantee_type: 'user', grantee_id: currentUserId },
                                    ...(userGroupIds.length > 0 ? [{ grantee_type: 'group', grantee_id: { in: userGroupIds } }] : []),
                                ],
                            },
                        },
                    },
                },
                {
                    AND: [
                        { document_package_header_id: null },
                        { user_id_creator: currentUserId } 
                    ]
                }
            ],
        };


        const where = {
            company_id: parseInt(company_id),
            AND: [
                ...filterConditions,
                permissionClause,    
            ],
        };

        if (where.AND.length === 0) {
            delete where.AND;
        }

        const [total, results] = await db.$transaction([
           db.document_packages_signers.count({ where }),
            db.document_packages_signers.findMany({
                where,
                skip,
                take: itemsPerPage,
                orderBy: { id: 'desc' },
                include: {
                    company: true,
                    document_packages_header: { select: { name: true } },
                    documents: { select: { id: true, name: true }, orderBy: { id: 'asc' } },
                    signers: {
                        select: {
                            status: true,
                            signed_at: true,
                            user_id: true,
                            order: true,

                            users: {
                                select: {
                                    firstname: true,
                                    lastname: true,
                                    email: true,
                                    id_type: true,
                                    id_number: true,
                                    doc_type: true
                                },

                            }
                        }
                    }

                },
            }),
        ]);

        const companyAdvancedOptions = await db.company_advanced_options.findFirst({ where: { company_id: realCompanyId } });

        const formattedData = results.map(item => {

            const { company, signers, documents, document_packages_header, ...rest } = item;

            const targetSigner = item.signers.find(s => s.order === 2) || item.signers.find(s => s.order === 1);

            const targetUser = targetSigner?.users;
            const total_signers = signers.length;
            const completed_signers = signers.filter(s => s.status === 'accepted').length;

            const signers_request = {
                order: signers.map(s => s.order).join(','),
                status_request: signers.map(s => s.status).join(','),
                user_id_request: signers.map(s => s.user_id).join(','), 
            };

            const statusMap = { send: "0", accepted: "1", rejected: "2", canceled: "3", expired: "4", blocked: "5", scheduled: "6", "": "" };
            const _status = statusMap[rest.status?.trim() || ""];

            return {
                id: rest.id,
                document_package_header_id: rest.document_package_header_id,
                package_name: document_packages_header?.name,
                processing_status: rest.processing_status,
                created_at: rest.created_at,
                updated_at: rest.updated_at,
                name: `${targetUser?.firstname || ''} ${targetUser?.lastname || ''}`,
                firstname: targetUser?.firstname,
                lastname: targetUser?.lastname,
                templates: documents.map(doc => ({ 
                    id: doc.id, name: doc.name, request_id: rest.id, is_pdf: rest.is_pdf, 
                    is_allowed: companyAdvancedOptions?.is_editing_document_allowed 
                })),
                total_signers,
                completed_signers,
                signers_request,
                status: _status,
                is_pdf: rest.is_pdf,
                signer: {
                    firstname: targetUser?.firstname,
                    lastname: targetUser?.lastname,
                    email: targetUser?.email,
                    id_type: targetUser?.doc_type.abbreviation,
                    id_number: targetUser?.id_number,
                    user_id: targetUser?.id,
                },
                company: {
                    company_id: company.id,
                    company_name: company.company_name,
                    fiscal_name: company.fiscal_name,
                },
            };
        });

        res.status(200).send({
            status: true,
            total,
            current_page: page,
            total_pages: Math.ceil(total / itemsPerPage),
            data: formattedData,
        });

    } catch (err) {
        console.error("Error fetching sign requests:", err);
        res.status(500).send({
            status: false,
            message: "An internal server error occurred.",
            error: process.env.NODE_ENV === 'development' ? err.message : undefined,
        });
    }
}

