async function signPdf(req, res) {
    try {

        const tokenPayload = jwt.verify(req.body.token, config.SECRET_TOKEN);
        const { documentPackageSigner, signers, user } = await getPackageAndSignersData(tokenPayload);

        if (!documentPackageSigner) {
            return res.status(404).send({ message: "No se encontró el paquete de documentos." });
        }

        const userSigner = documentPackageSigner.signers[0];
        const signedDocuments = await processPdfsWithLambda(
            documentPackageSigner,
            req.body.sign,
            userSigner.order
        );

        const signUrl = await service.uploadSignToS3(
            documentPackageSigner.company_id,
            tokenPayload.document_package_signer_id,
            req.body.sign
        );

        await updateSignerStatusAndLog(tokenPayload, req, signUrl);

        const signedAt = new Date();
        const options = { timeZone: 'America/Bogota' };
        const date = signedAt.toLocaleDateString('es-CO', options);
        const time = signedAt.toLocaleTimeString('es-CO', options);

        service.sendAgradecimientoSolicitudFirma(
            user.email,
            documentPackageSigner.company.avatar,
            `${user.firstname} ${user.lastname}`,
            documentPackageSigner.company.fiscal_name,
            date,
            time,
            documentPackageSigner.company.email
        );

        await checkAndFinalizePdfPackage(tokenPayload, documentPackageSigner, signers, signedDocuments);

        return res.status(200).send({
            status: true,
            message: 'Documento firmado correctamente',
        });

    } catch (error) {
        console.error('Error en signPdf:', error);
        res.status(500).json({ status: false, message: error.message || 'Error al firmar el PDF' });
    }
}

async function processPdfsWithLambda(documentPackageSigner, signImage, userOrder) {
    const signedDocuments = [];

    const logoBase64 = await fetchImageAsBase64('https://publicofirmadigital.s3.amazonaws.com/assets/img/templates/vertical_logo_qs.png');

    for (const document of documentPackageSigner.documents) {
        const fields = JSON.parse(document.fields || '[]');

        const specificField = fields.filter(field => {
            const fieldNameMatch = field.name.match(/\[\$FIRMA(\d+)\]/);
            return fieldNameMatch && parseInt(fieldNameMatch[1]) === userOrder;
        });

        const lambdaPayload = {
            pdf_url: buildS3Url(document.s3_key),
            sign_image: addBase64Padding(signImage),
            fields: specificField,
            url: document.s3_key,
            logo_image: addBase64Padding(logoBase64),
            index: userOrder,
            folder: process.env.S3_FOLDER,
            bucket: process.env.S3_BUCKET_PREFIX,
        };

        const command = new InvokeCommand({
            FunctionName: 'updatePdfContentTest',
            Payload: JSON.stringify(lambdaPayload),
        });
        const response = await lambdaClient.send(command);
        const resultPayload = JSON.parse(new TextDecoder().decode(response.Payload));


        if (resultPayload.statusCode !== 200) {
            console.error("Error en Lambda al firmar el documento:", resultPayload);
        }

        signedDocuments.push({ name: document.name, key: document.s3_key, id: document.id });
    }

    return signedDocuments;
}

async function fetchImageAsBase64(url) {
    const response = await axios.get(url, { responseType: 'arraybuffer' });
    const base64Image = Buffer.from(response.data, 'binary').toString('base64');
    return base64Image;
}

function buildS3Url(key) {
  const bucket = process.env.S3_BUCKET_PREFIX;
  const folder = process.env.S3_FOLDER;

  let path = key;

  if (folder && folder.trim() !== '') {
    const encodedFolder = encodeURIComponent(folder);
    path = `${encodedFolder}/${key}`;
  }

  return `https://${bucket}.s3.amazonaws.com/${path}`;
}

function addBase64Padding(base64String) {
    return base64String + '='.repeat((4 - base64String.length % 4) % 4);
}

async function checkAndFinalizePdfPackage(tokenPayload, documentPackageSigner, signers, signedDocuments) {
    const statusRequest = await db.document_signers.findMany({
        where: { document_package_signer_id: parseInt(tokenPayload.document_package_signer_id) },
        select: { status: true }
    });

    const allAccepted = statusRequest.every(record => record.status === "accepted");

    if (allAccepted) {

        const packageConsumed = await manageCompanyPackageUnits(
            documentPackageSigner.company.id,
            documentPackageSigner.id
        );

        const updatedPackage = await db.document_packages_signers.update({
            where: { id: parseInt(tokenPayload.document_package_signer_id) },
            data: { status: 'accepted', signed_at: new Date(), processing_status: packageConsumed ? 1 : 0, updated_at: new Date() },
        });

        const signedPdfBuffers = await getSignedPdfBuffersFromS3(signedDocuments);
        const documentHashes = await getDocumentHashes(documentPackageSigner.documents);
        setImmediate(() => updateHashDocumentSigned(tokenPayload.document_package_signer_id).catch(console.error));

        if (packageConsumed) {

            await sendCompletionNotificationsWithAttachments(
                documentPackageSigner,
                signers,
                updatedPackage,
                signedPdfBuffers,
                documentHashes,
                documentPackageSigner.package_name
            );

        }
    }
}

async function sendCompletionNotificationsWithAttachments(documentPackageSigner, signers, updatedPackage, signedPdfBuffers, documentHashes, packageName) {
    const company = documentPackageSigner.company;

    const date = new Date(updatedPackage.updated_at).toLocaleDateString('es-CO');
    const time = new Date(updatedPackage.updated_at).toLocaleTimeString('es-CO');

    for (const signer of signers) {
